/** Public-store regression for statement/term reindexing through shared {@link StoreProperties}. */
public final class LmdbStoreSharedPropertiesReindexTest {

	private static final String INITIAL_TRIPLE_INDEXES = "spoc,posc";
	private static final String FIRST_REINDEXED_TRIPLE_INDEXES = "spoc,posc,ospc,cspo,cpos,cosp";
	private static final String INITIAL_TERM_INDEXES = "spoc,cspo";
	private static final String NONDEFAULT_ONLY_TERM_INDEXES = "ospc";
	private static final String FIRST_REINDEXED_TERM_INDEXES = "spoc,cspo,ospc";
	private static final String SECOND_REINDEXED_TERM_CONFIG = "spoc,cspo,ospc,cpos";
	// Persisted topology follows TripleIndex's canonical order while the request deliberately uses a different order.
	private static final String SECOND_REINDEXED_TERM_INDEXES = "spoc,cspo,cpos,ospc";
	private static final long DATABASE_SIZE = 32L * 1024 * 1024;

	private static final IRI KNOWN_SUBJECT = Values.iri("urn:shared-properties:subject");
	private static final IRI KNOWN_PREDICATE = Values.iri("urn:shared-properties:predicate");
	private static final IRI KNOWN_CONTEXT = Values.iri("urn:shared-properties:context");
	private static final IRI KNOWN_INFERRED_PREDICATE = Values.iri("urn:shared-properties:inferred-predicate");
	private static final TripleTerm KNOWN_TRIPLE_TERM = Values.tripleTerm(
			Values.iri("urn:shared-properties:triple-subject"),
			Values.iri("urn:shared-properties:triple-predicate"),
			Values.literal("triple-object"));

	@Test
	void publicStoreReindexPopulatesBothIndexFamiliesAndPersistsMetadata(@TempDir File dataDir) throws Exception {
		SeedWitness seed = seedStore(dataDir);

		IdWitness firstReopen = reopenAndVerify(dataDir, FIRST_REINDEXED_TRIPLE_INDEXES,
				FIRST_REINDEXED_TERM_INDEXES, seed);
		assertMetadata(dataDir, FIRST_REINDEXED_TRIPLE_INDEXES, FIRST_REINDEXED_TERM_INDEXES);

		// Change only the term-index set. This isolates StoreProperties.dirty handling from statement reindexing.
		IdWitness secondReopen = reopenAndVerify(dataDir, FIRST_REINDEXED_TRIPLE_INDEXES,
				SECOND_REINDEXED_TERM_CONFIG, SECOND_REINDEXED_TERM_INDEXES, seed);
		assertEquals(firstReopen, secondReopen, "reindexing must preserve value IDs");
		assertMetadata(dataDir, FIRST_REINDEXED_TRIPLE_INDEXES, SECOND_REINDEXED_TERM_INDEXES);

		// A third open proves that the second reopen's metadata was actually persisted, rather than retained in memory.
		IdWitness persistedReopen = reopenAndVerify(dataDir, FIRST_REINDEXED_TRIPLE_INDEXES,
				SECOND_REINDEXED_TERM_INDEXES, seed);
		assertEquals(secondReopen, persistedReopen, "persisted reindex metadata must preserve value IDs");
		assertMetadata(dataDir, FIRST_REINDEXED_TRIPLE_INDEXES, SECOND_REINDEXED_TERM_INDEXES);
	}

	@Test
	void termOnlyReindexPersistsDirtyMetadataAcrossSecondReopen(@TempDir File dataDir) throws Exception {
		SeedWitness seed = seedStore(dataDir);

		IdWitness firstReopen = reopenAndVerify(dataDir, INITIAL_TRIPLE_INDEXES,
				SECOND_REINDEXED_TERM_CONFIG, SECOND_REINDEXED_TERM_INDEXES, seed);
		assertMetadata(dataDir, INITIAL_TRIPLE_INDEXES, SECOND_REINDEXED_TERM_INDEXES);

		IdWitness secondReopen = reopenAndVerify(dataDir, INITIAL_TRIPLE_INDEXES,
				SECOND_REINDEXED_TERM_CONFIG, SECOND_REINDEXED_TERM_INDEXES, seed);
		assertEquals(firstReopen, secondReopen, "term-only reindexing must preserve value IDs");
		assertMetadata(dataDir, INITIAL_TRIPLE_INDEXES, SECOND_REINDEXED_TERM_INDEXES);
	}

	@Test
	void nonDefaultOnlyTermConfigPersistsCompleteTopologyForBlankReopen(@TempDir File dataDir) throws Exception {
		String expectedTermIndexes = orderedTermIndexes(NONDEFAULT_ONLY_TERM_INDEXES + ",spoc,cspo");
		SeedWitness seed = seedStore(dataDir, NONDEFAULT_ONLY_TERM_INDEXES);

		assertMetadata(dataDir, INITIAL_TRIPLE_INDEXES, expectedTermIndexes);
		IdWitness reopened = reopenAndVerify(dataDir, INITIAL_TRIPLE_INDEXES, "", expectedTermIndexes, seed);
		assertEquals(seed.ids(), reopened, "blank term-index configuration must preserve value IDs");
		assertMetadata(dataDir, INITIAL_TRIPLE_INDEXES, expectedTermIndexes);
	}

	private static SeedWitness seedStore(File dataDir) throws Exception {
		return seedStore(dataDir, INITIAL_TERM_INDEXES);
	}

	private static SeedWitness seedStore(File dataDir, String termIndexes) throws Exception {
		LmdbStoreConfig config = config(INITIAL_TRIPLE_INDEXES, termIndexes);
		LmdbStore store = new LmdbStore(dataDir, config);
		try {
			store.init();
			try (LmdbStoreConnection connection = (LmdbStoreConnection) store.getConnection()) {
				connection.begin();
				for (int i = 0; i < 48; i++) {
					IRI subject = i == 0 ? KNOWN_SUBJECT : Values.iri("urn:shared-properties:subject:" + i);
					IRI predicate = i == 0 ? KNOWN_PREDICATE
							: Values.iri("urn:shared-properties:predicate:" + (i % 4));
					Value object = i == 0 ? KNOWN_TRIPLE_TERM : Values.literal("explicit-object-" + i);
					Resource context = i == 0 ? KNOWN_CONTEXT
							: Values.iri("urn:shared-properties:context:" + (i % 5));
					connection.addStatement(subject, predicate, object, context);
				}
				for (int i = 0; i < 16; i++) {
					connection.addInferredStatement(
							Values.iri("urn:shared-properties:inferred-subject:" + i),
							KNOWN_INFERRED_PREDICATE,
							Values.literal("inferred-object-" + i),
							Values.iri("urn:shared-properties:inferred-context:" + (i % 3)));
				}
				connection.commit();
			}

			LmdbStats stats = store.getLmdbStats();
			long explicitRows = required(stats.tripleDatabases(), statementDatabase("spoc", true)).entries();
			long inferredRows = required(stats.tripleDatabases(), statementDatabase("spoc", false)).entries();
			long termRows = required(stats.valueDatabases(), termDatabase("spoc")).entries();
			assertTrue(explicitRows > 0, "seed store must contain explicit rows");
			assertTrue(inferredRows > 0, "seed store must contain inferred rows");
			assertTrue(termRows > 0, "seed store must contain triple-term rows");
			return new SeedWitness(explicitRows, inferredRows, termRows, readKnownIds(store));
		} finally {
			store.shutDown();
		}
	}

	private static IdWitness reopenAndVerify(File dataDir, String tripleIndexes, String termIndexes,
			SeedWitness seed) throws Exception {
		return reopenAndVerify(dataDir, tripleIndexes, termIndexes, termIndexes, seed);
	}

	private static IdWitness reopenAndVerify(File dataDir, String tripleIndexes, String termIndexes,
			String expectedTermIndexes, SeedWitness seed) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, config(tripleIndexes, termIndexes));
		try {
			store.init();
			LmdbStats stats = store.getLmdbStats();
			for (String index : tripleIndexes.split(",")) {
				assertEquals(seed.explicitRows(),
						required(stats.tripleDatabases(), statementDatabase(index, true)).entries(),
						"explicit index is incomplete: " + index);
				assertEquals(seed.inferredRows(),
						required(stats.tripleDatabases(), statementDatabase(index, false)).entries(),
						"inferred index is incomplete: " + index);
			}
			for (String index : expectedTermIndexes.split(",")) {
				assertEquals(seed.termRows(), required(stats.valueDatabases(), termDatabase(index)).entries(),
						"triple-term index is incomplete: " + index);
			}

			assertKnownStatementsAndTerms(store);
			IdWitness ids = readKnownIds(store);
			assertEquals(seed.ids(), ids, "reindexing must not rewrite value IDs");
			return ids;
		} finally {
			store.shutDown();
		}
	}

	private static void assertKnownStatementsAndTerms(LmdbStore store) throws Exception {
		try (LmdbStoreConnection connection = (LmdbStoreConnection) store.getConnection()) {
			try (CloseableIteration<? extends Statement> statements = connection.getStatements(KNOWN_SUBJECT,
					KNOWN_PREDICATE, KNOWN_TRIPLE_TERM, true, KNOWN_CONTEXT)) {
				assertTrue(statements.hasNext(), "the known contextual triple-term statement is missing");
				Statement statement = statements.next();
				assertEquals(KNOWN_TRIPLE_TERM, statement.getObject(), "the triple-term value changed during reindex");
				assertFalse(statements.hasNext(), "the known statement must remain unique");
			}

			long inferredRows = 0;
			try (CloseableIteration<? extends Statement> statements = connection.getStatements(null,
					KNOWN_INFERRED_PREDICATE, null, true)) {
				while (statements.hasNext()) {
					statements.next();
					inferredRows++;
				}
			}
			assertEquals(16, inferredRows, "inferred rows changed during reindex");
		}
	}

	private static IdWitness readKnownIds(LmdbStore store) throws Exception {
		try (LmdbStoreConnection connection = (LmdbStoreConnection) store.getConnection();
				CloseableIteration<? extends Statement> statements = connection.getStatements(KNOWN_SUBJECT,
						KNOWN_PREDICATE, KNOWN_TRIPLE_TERM, true, KNOWN_CONTEXT)) {
			assertTrue(statements.hasNext(), "the known statement is required for the ID oracle");
			Statement statement = statements.next();
			LmdbValue subject = assertInstanceOf(LmdbValue.class, statement.getSubject());
			LmdbValue object = assertInstanceOf(LmdbValue.class, statement.getObject());
			subject.init();
			object.init();
			assertTrue(subject.getInternalID() != LmdbValue.UNKNOWN_ID, "subject ID was not assigned");
			assertTrue(object.getInternalID() != LmdbValue.UNKNOWN_ID, "triple-term ID was not assigned");
			return new IdWitness(subject.getInternalID(), object.getInternalID());
		}
	}

	private static void assertMetadata(File dataDir, String tripleIndexes, String termIndexes) throws IOException {
		Properties properties = new Properties();
		File propertiesFile = new File(dataDir, StoreProperties.FILE_NAME);
		try (InputStream input = new FileInputStream(propertiesFile)) {
			properties.load(input);
		}
		assertEquals(tripleIndexes, properties.getProperty(StoreProperties.INDEXES_KEY));
		assertEquals(termIndexes, properties.getProperty(StoreProperties.TRIPLE_TERM_INDEXES_KEY));
	}

	private static LmdbStoreConfig config(String tripleIndexes, String termIndexes) {
		return new LmdbStoreConfig(tripleIndexes)
				.setTripleTermIndexes(termIndexes)
				.setTripleDBSize(DATABASE_SIZE)
				.setValueDBSize(DATABASE_SIZE)
				.setAutoGrow(true);
	}

	private static String orderedTermIndexes(String termIndexes) throws Exception {
		return String.join(",", TripleIndex.orderIndexSpecs(TripleIndex.parseIndexSpecList(termIndexes)));
	}

	private static LmdbDatabaseStats required(Map<String, LmdbDatabaseStats> stats, String database) {
		LmdbDatabaseStats result = stats.get(database);
		assertNotNull(result, "missing LMDB database: " + database);
		return result;
	}

	private static String statementDatabase(String index, boolean explicit) {
		String name = index + index;
		return explicit ? name : name + "-inf";
	}

	private static String termDatabase(String index) {
		String name = "term-" + index;
		return name + name;
	}

	private record SeedWitness(long explicitRows, long inferredRows, long termRows, IdWitness ids) {
	}

	private record IdWitness(long subjectId, long tripleTermId) {
	}
}
